  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])

    # Build node map and children lists
    node_map = {}
    children = {}
    for node in nodes:
        nid = node['id']
        node_map[nid] = node
        children.setdefault(node['parent'], []).append(nid)

    # Root is the node with parent None
    # Determine order: depth descending, then id ascending
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))

    removed = set()
    removed_order = []

    for node in sorted_nodes:
        nid = node['id']
        if nid in removed:
            continue
        # Never remove root or required-symbol nodes
        if node['parent'] is None or node['symbol'] in required_symbols:
            continue
        if not node['removable']:
            continue
        # Check if any child is still retained
        child_ids = children.get(nid, [])
        has_retained_child = any(cid not in removed for cid in child_ids)
        if has_retained_child:
            continue
        # Safe to remove
        removed.add(nid)
        removed_order.append(nid)

    retained = sorted([n['id'] for n in nodes if n['id'] not in removed])
    return {
        'removed_node_ids': removed_order,
        'retained_node_ids': retained
    }
